<?php use Camagru\Http\Http; use Camagru\Config; ?>
<section class="photo-detail"><a class="back-link" href="/gallery">← Back to the roll</a><div class="detail-layout"><div class="detail-image"><img src="/media/<?= (int) $photo['id'] ?>/image" alt="A creation by <?= Http::escape($photo['username']) ?>" width="<?= (int) $photo['width'] ?>" height="<?= (int) $photo['height'] ?>"></div><div class="detail-panel"><span class="eyebrow">ONE LITTLE MOMENT</span><h1>By <?= Http::escape($photo['username']) ?>.</h1><time class="muted" datetime="<?= Http::escape($photo['created_at']) ?>"><?= Http::escape(date('F j, Y', strtotime($photo['created_at']))) ?></time>
<div class="detail-actions">
<?php if ($user): ?><form method="post" action="/photos/<?= (int) $photo['id'] ?>/<?= $photo['liked'] ? 'unlike' : 'like' ?>" data-ajax="like"><input type="hidden" name="csrf" value="<?= Http::escape($_SESSION['csrf']) ?>"><button type="submit" class="button button-outline like-button" aria-pressed="<?= $photo['liked'] ? 'true' : 'false' ?>"><?= $photo['liked'] ? '♥' : '♡' ?> <span class="like-count"><?= (int) $photo['likes'] ?></span> likes</button></form><?php else: ?><a href="/login" class="button button-outline">♡ <?= (int) $photo['likes'] ?> · Sign in to like</a><?php endif; ?>
<button class="text-button share-button" type="button" data-url="<?= Http::escape(Config::url('/photos/' . $photo['id'])) ?>">Share ↗</button></div>
<div class="share-fallback" hidden><label>Copy this link to your favorite social app<input readonly value="<?= Http::escape(Config::url('/photos/' . $photo['id'])) ?>"></label></div>
<?php if ($user && (int) $user['id'] === (int) $photo['user_id']): ?><form method="post" action="/photos/<?= (int) $photo['id'] ?>/delete" data-ajax="delete"><input type="hidden" name="csrf" value="<?= Http::escape($_SESSION['csrf']) ?>"><button type="submit" class="text-button danger">Delete this creation</button></form><?php endif; ?>
<section class="comments-section" aria-labelledby="comments-title"><h2 id="comments-title">A little conversation.</h2><div id="comments"><?php foreach ($comments as $comment): ?><article class="comment"><strong><?= Http::escape($comment['username']) ?></strong><p><?= Http::escape($comment['body']) ?></p></article><?php endforeach; ?></div><?php if (!$comments): ?><p id="no-comments" class="muted">Be the first to say something kind.</p><?php endif; ?>
<?php if ($page > 1 || count($comments) === 20): ?><nav class="pagination" aria-label="Comment pages"><?php if ($page > 1): ?><a href="?page=<?= $page-1 ?>">← Previous</a><?php endif; ?><?php if (count($comments) === 20): ?><a href="?page=<?= $page+1 ?>">More comments →</a><?php endif; ?></nav><?php endif; ?>
<?php if ($user): ?><form method="post" action="/photos/<?= (int) $photo['id'] ?>/comments" class="stack-form" data-ajax="comment"><input type="hidden" name="csrf" value="<?= Http::escape($_SESSION['csrf']) ?>"><input type="hidden" name="submission" value="<?= bin2hex(random_bytes(16)) ?>"><label>Leave a note<textarea name="body" maxlength="1000" rows="3" required placeholder="A little kindness goes a long way…"></textarea></label><button class="button" type="submit">Post comment ↗</button><p class="form-status" role="status"></p></form><?php else: ?><p class="muted"><a href="/login">Sign in</a> to join the conversation.</p><?php endif; ?>
</section></div></div></section>
